function (currentState, data) {
                var newState = currentState;
                var customData = data.getCustomData();
                switch (currentState) {
                    case 0 /* BaseGameSpin */:
                        if (data.isBonusTriggered()) {
                            if (this.customFeatureInfo != null) {
                                switch (this.customFeatureInfo.featureindex) {
                                    case "1":
                                        var rwInfo = this.getRandomWildFeatureInfo();
                                        if (rwInfo != null && rwInfo != undefined) {
                                            newState = 1 /* BaseGameRandomWild */;
                                        }
                                        else {
                                            newState = 4 /* BaseGameSpinTriggerFreeSpin */;
                                        }
                                        break;
                                    case "2":
                                        var rwInfo = this.getRandomWildFeatureInfo();
                                        if (rwInfo != null && rwInfo != undefined) {
                                            newState = 1 /* BaseGameRandomWild */;
                                        }
                                        else {
                                            newState = 2 /* PickGameTrigger */;
                                        }
                                        break;
                                    case "3":
                                        newState = 1 /* BaseGameRandomWild */;
                                        break;
                                    default:
                                        newState = 0 /* BaseGameSpin */;
                                        break;
                                }
                            }
                        }
                        break;
                    case 1 /* BaseGameRandomWild */:
                        break;
                    case 2 /* PickGameTrigger */:
                        newState = 3 /* PickGame */;
                        break;
                    case 3 /* PickGame */:
                        break;
                    case 5 /* BonusGameSpin */:
                        if (data.isBonusTriggered()) {
                            if (this.customFeatureInfo != null) {
                                var rwInfo = this.getRandomWildFeatureInfo();
                                if (rwInfo != null && rwInfo != undefined) {
                                    newState = 6 /* BonusGameRandomWild */;
                                }
                                else if (this.customFeatureInfo.currentFreeSpinsAwarded > -1) {
                                    newState = 7 /* BonusGameSpinReTrigger */;
                                }
                                else {
                                    newState = 5 /* BonusGameSpin */;
                                }
                            }
                        }
                        else if (this.customFeatureInfo.freeSpinsRemaining == 0) {
                            newState = 8 /* BonusGameEnd */;
                        }
                        break;
                    case 7 /* BonusGameSpinReTrigger */:
                        break;
                    case 4 /* BaseGameSpinTriggerFreeSpin */:
                        newState = 5 /* BonusGameSpin */;
                        break;
                    case 8 /* BonusGameEnd */:
                        newState = 0 /* BaseGameSpin */;
                        break;
                }
                return newState;
            }

spinComplete.source:
function () {
                switch (this.gameState) {
                    case 1 /* BaseGameRandomWild */:
                        luckytree.Config.IDLE_STATE = false;
                        //this.treeAnimationController.playTransition(true);
                        this.canPlayTreeAnimation(false, true);
                        this.audioController.playTreeMoveSnd();
                        switch (this.customFeatureInfo.featureindex) {
                            case "1":
                                this.gameState = 4 /* BaseGameSpinTriggerFreeSpin */;
                                break;
                            case "2":
                                this.gameState = 2 /* PickGameTrigger */;
                                break;
                            default:
                                this.gameState = 0 /* BaseGameSpin */;
                                break;
                        }
                        break;
                    case 6 /* BonusGameRandomWild */:
                        this.canPlayTreeAnimation(false, true);
                        this.audioController.playTreeMoveSnd();
                        if (this.customFeatureInfo.currentFreeSpinsAwarded > -1) {
                            this.gameState = 7 /* BonusGameSpinReTrigger */;
                        }
                        else {
                            this.gameState = 5 /* BonusGameSpin */;
                        }
                        break;
                    case 8 /* BonusGameEnd */:
                        // transition back to base game
                        this.gameState = 0 /* BaseGameSpin */;
                        break;
                    case 0 /* BaseGameSpin */:
                        // Base game spin complete
                        this.spinCount++;
                        this.canPlayTreeAnimation(false);
                        this.slot.setGaffingEnabled(true);
                        var customData = this.gameData.getCustomData();
                        if (customData.getIsMaxWin()) {
                            var baseGameData = customData.getBaseGameData();
                            this.uiController.showMaxWinPopup(true, customData.getMaxWinValue(), 0 /* BaseGame */, null);
                            this.uiController.handleMaxWinHit(this.gameData);
                        }
                        else {
                            if (this.totalWin > 0)
                                this.uiController.showSkipButton(true);
                            this.slot.getWinDisplayController().start(true);
                        }
                        break;
                    case 2 /* PickGameTrigger */:
                        this.uiController.stopAutoPlay();
                        luckytree.Config.IDLE_STATE = false;
                        this.slot.getSymbolAnimationController().checkForSymbolHighlight();
                        break;
                    case 3 /* PickGame */:
                        break;
                    case 4 /* BaseGameSpinTriggerFreeSpin */:
                        this.uiController.stopAutoPlay();
                        luckytree.Config.IDLE_STATE = false;
                        this.slot.getSymbolAnimationController().checkForSymbolHighlight();
                        break;
                    case 7 /* BonusGameSpinReTrigger */:
                        // Bonus game (re)triggered from bonus game
                        this.freeSpin.getSymbolAnimationController().checkForSymbolHighlight();
                        break;
                    case 5 /* BonusGameSpin */:
                        var customData = this.gameData.getCustomData();
                        if (customData.getIsMaxWin()) {
                            var baseGameData = customData.getBaseGameData();
                            this.uiController.setFreeSpinWin(customData.getMaxWinValue() - baseGameData.getTotalWin());
                            this.slot.getWinDisplayController().configure(this.triggerSpinData);
                            this.uiController.showMaxWinPopup(true, customData.getMaxWinValue(), 1 /* FreeSpin */, this.endFreeSpinBonus.bind(this));
                        }
                        else {
                            this.freeSpin.setGaffingEnabled(true);
                            if (this.gameData.getAllSlotResults().length > 0) {
                                this.uiController.enableSkipButton(true);
                            }
                            // Bonus game spin complete
                            this.uiController.setFreeSpinWin(this.customFeatureInfo.freeSpinTotalWin);
                            this.freeSpin.getWinDisplayController().start(true);
                        }
                        break;
                    case 9 /* Recovering */:
                        break;
                    default:
                        break;
                }
            }

bangupComplete.source:
function () {
                if (this.partnerListener != undefined) {
                    if (this.partnerListener.winDisplayEventListener) {
                        this.partnerListener.winDisplayEventListener.handleWinDisplayEvent({
                            "winAmount": this.getWin()
                        });
                    }
                }
                if (this.isRealMoney) {
                    // Only force update the balance in real money mode. In free play, balance is updated at
                    // separately.
                    this.updateBalance(this.getBalance(), luckytree.Config.OUTCOME);
                }
                if (this.historyData == null && this.inFreeSpins == false) {
                    this.logic.sendEndGame();
                }
                this.spinButtonEnableTracker.dependencyMet(UIController.EventBangupComplete);
            }

