requestDTO.source:
function (wager, slot) {
                if (slot === void 0) { slot = null; }
                var sl = (slot == null) ? this.slot : slot;
                var payloads = [];
                var payload = new luckytree.LTWagerPayload(wager.getTotalBet());
                payloads.push(payload);
                if (this.historyReplayData != null) {
                    payloads.push(new glscomms.ReplayRequestPayload(this.historyReplayData.getNextState()));
                }
                if (sl.shouldGaff()) {
                    payloads.push(new luckytree.GaffPayload(sl.getGaffStops(), sl.getGaffReelIndex(), sl.getGaffingType()));
                }
                sl.setGaffingType(0);
                return payloads;
            }

actualBonusSelector.source:
function (gameData, node, isBonusTrigger, isBonusPay, totalBonusWin) {
                if (isBonusTrigger === void 0) { isBonusTrigger = false; }
                if (isBonusPay === void 0) { isBonusPay = false; }
                if (totalBonusWin === void 0) { totalBonusWin = -1; }
                var spinNode = node.childNodes;
                for (var spinNodeIndex = 0; spinNodeIndex < spinNode.length; ++spinNodeIndex) {
                    // Parse spin data child nodes
                    var spinDataSource = spinNode[spinNodeIndex].childNodes;
                    for (var spinDataIndex = 0; spinDataIndex < spinDataSource.length; ++spinDataIndex) {
                        var spinDataSubType = spinDataSource[spinDataIndex];
                        var nodeType = spinDataSubType.nodeName;
                        if (nodeType == "ReelStops") {
                            gameData.setStopPositions(spinDataSubType.textContent.split("|").map(Number));
                        }
                        else if (nodeType == "PaylineWin") {
                            this.populatePaylineWin(gameData, spinDataSubType);
                        }
                        else if (nodeType == "AnywayWin") {
                            this.populateAnywayWin(gameData, spinDataSubType);
                        }
                        else if (nodeType == "ScatterWin") {
                            this.populateScatterWin(gameData, spinDataSubType, isBonusTrigger, isBonusPay, totalBonusWin);
                        }
                    }
                    // Parse spin data attributes (at root level of this node only)
                    var spinDataAttr = spinNode[spinNodeIndex].attributes;
                    var isBonusNode = spinDataAttr.getNamedItem("bonusAwarded");
                    if (isBonusNode != null) {
                        gameData.setIsBonusTriggered((isBonusNode.value == "Y"));
                    }
                }
            }

actualGameResultMoney.source:
function (gameData, node, isBaseRecovery, isBonusTrigger, isBonusPay, totalFreeSpinsWin) {
                if (isBaseRecovery === void 0) { isBaseRecovery = false; }
                if (isBonusTrigger === void 0) { isBonusTrigger = false; }
                if (isBonusPay === void 0) { isBonusPay = false; }
                if (totalFreeSpinsWin === void 0) { totalFreeSpinsWin = -1; }
                var totalWin;
                if (!isBaseRecovery) {
                    totalWin = parseInt(node.attributes.getNamedItem("totalWin").value, 10);
                    gameData.setWager(parseInt(node.attributes.getNamedItem("stake").value, 10));
                }
                else {
                    var reelNode = node.childNodes[0].childNodes[0];
                    totalWin = parseInt(reelNode.attributes.getNamedItem("spinWins").value, 10);
                }
                gameData.setTotalWin(totalWin);
                var reelsNode = node.childNodes;
                for (var i = 0; i < reelsNode.length; ++i) {
                    if (reelsNode[i].nodeName === "BaseGameRecoveryInfo") {
                        if (reelsNode[i].childNodes[0].nodeName === "ReelResults") {
                            var spinWins = parseInt(reelsNode[i].childNodes[0].childNodes[0].attributes.getNamedItem("spinWins").value, 10);
                            gameData.setTotalWin(totalWin + spinWins);
                            this.populateResults(gameData, reelsNode[i].childNodes[0]);
                        }
                        break;
                    }
                    if (reelsNode[i].nodeName == "ReelResults") {
                        this.populateResults(gameData, reelsNode[i], isBonusTrigger, isBonusPay, totalFreeSpinsWin);
                        break;
                    }
                }
            }

actualReplyConsumer.source:
function (xml) {
                var platformData = this.parsePlatformData(xml);
                var balanceData = glscomms.BalanceData.parseXML(xml.getElementsByTagName("Balances")[0]);
                var response = new glscomms.PlayResponse(platformData, balanceData);
                // Parse custom game data
                var resultTag = xml.getElementsByTagName("GameResult")[0];
                var gameData = response.getGameData();
                luckytree.LTGamePlayDataXMLParser.populateGameData(gameData, resultTag);
                var baseGameInfo = xml.getElementsByTagName("BaseGame")[0];
                //Maxwin data
                var isMaxWin = luckytree.LTGamePlayDataXMLParser.extractBoolAttribute("isMaxWin", baseGameInfo.attributes);
                var maxWinValue = Number(baseGameInfo.attributes.getNamedItem("maxWinValue").value);
                var currentSpinWin = gameData.getTotalWin();
                if (baseGameInfo.attributes.getNamedItem("totalWagerWin") != undefined) {
                    var totalWin = parseInt(baseGameInfo.attributes.getNamedItem("totalWagerWin").value, 10);
                    gameData.setTotalWin(totalWin);
                }
                var BGReelData;
                var reelList = xml.getElementsByTagName("ReelSpin")[0];
                var reelDataSource = reelList.attributes;
                var reelData = reelDataSource.getNamedItem("reelsetIndex").value;
                var customFeatureInfo;
                //Feature Tag Info
                var featureTag = xml.getElementsByTagName("Feature");
                var isFeatureTriggered = false;
                var totalBonusWin = -1;
                var isBonusPay = false;
                if (featureTag.length > 0) {
                    var featureTagDataSource = featureTag[0].attributes;
                    var featureIndex = featureTagDataSource.getNamedItem("index").value;
                    switch (featureIndex) {
                        case "1":
                            isFeatureTriggered = true;
                            console.log("Free Spins Triggered");
                            var freeSpinFeatureInfo = {
                                featureindex: featureIndex,
                                featurename: featureTagDataSource.getNamedItem("name").value,
                                freeSpinsStarted: false,
                                totalFreeSpinsAwarded: 0,
                                currentSpinNumber: 0,
                                freeSpinsRemaining: 0,
                                lastSpin: false,
                                currentFreeSpinsAwarded: -1,
                                freeSpinTotalWin: -1,
                                currentSpinWin: currentSpinWin,
                                randomWildFeatureInfo: null,
                                isMaxWin: isMaxWin
                            };
                            var dataNode = featureTag[0].childNodes[0];
                            if (dataNode != undefined) {
                                var dataAttr = dataNode.attributes;
                                if (dataAttr.getNamedItem("freeSpinsTotal") != undefined) {
                                    freeSpinFeatureInfo.totalFreeSpinsAwarded = Number(dataAttr.getNamedItem("freeSpinsTotal").value);
                                    freeSpinFeatureInfo.freeSpinsRemaining = freeSpinFeatureInfo.totalFreeSpinsAwarded;
                                }
                                else {
                                    freeSpinFeatureInfo.freeSpinsStarted = true;
                                    freeSpinFeatureInfo.totalFreeSpinsAwarded = Number(dataAttr.getNamedItem("totalFreeSpinsAwarded").value);
                                    freeSpinFeatureInfo.currentSpinNumber = Number(dataAttr.getNamedItem("currentSpinNumber").value) + 1;
                                    freeSpinFeatureInfo.freeSpinTotalWin = Number(dataAttr.getNamedItem("freeSpinTotalWin").value);
                                    freeSpinFeatureInfo.lastSpin = luckytree.LTGamePlayDataXMLParser.extractBoolAttribute("lastSpin", dataAttr);
                                    if (dataAttr.getNamedItem("currentFreeSpinsAwarded") != null && dataAttr.getNamedItem("currentFreeSpinsAwarded") != undefined) {
                                        freeSpinFeatureInfo.currentFreeSpinsAwarded = Number(dataAttr.getNamedItem("currentFreeSpinsAwarded").value);
                                    }
                                    freeSpinFeatureInfo.freeSpinsRemaining = freeSpinFeatureInfo.totalFreeSpinsAwarded - freeSpinFeatureInfo.currentSpinNumber;
                                    if (freeSpinFeatureInfo.currentFreeSpinsAwarded > -1) {
                                        freeSpinFeatureInfo.freeSpinsRemaining = freeSpinFeatureInfo.freeSpinsRemaining - freeSpinFeatureInfo.currentFreeSpinsAwarded;
                                    }
                                    isBonusPay = true;
                                    totalBonusWin = freeSpinFeatureInfo.freeSpinTotalWin;
                                }
                            }
                            if (featureTag.length > 1) {
                                freeSpinFeatureInfo.randomWildFeatureInfo = this.parseRandomFeatureInfo(featureTag);
                            }
                            customFeatureInfo = freeSpinFeatureInfo;
                            break;
                        case "2":
                            isFeatureTriggered = true;
                            console.log("Pick Bonus Triggered");
                            var pickBonusFeatureInfo = {
                                featureindex: featureIndex,
                                featurename: featureTagDataSource.getNamedItem("name").value,
                                pickBonusStarted: false,
                                featureTotalWin: parseInt(resultTag.attributes.getNamedItem("totalWin").value, 10),
                                pickLevel: -1,
                                pickData: null,
                                pickEnd: false,
                                randomWildFeatureInfo: null,
                                isMaxWin: isMaxWin,
                                maxWinValue: maxWinValue
                            };
                            var dataNode = featureTag[0].childNodes[0];
                            if (dataNode != undefined) {
                                pickBonusFeatureInfo.pickBonusStarted = true;
                                var dataAttr = dataNode.attributes;
                                pickBonusFeatureInfo.pickLevel = parseInt(dataAttr.getNamedItem("pickLevel").value, 10);
                                if (pickBonusFeatureInfo.pickLevel === 0) {
                                    var pData = {
                                        pickIndex: parseInt(dataAttr.getNamedItem("pickIndex").value, 10),
                                        selectedPicks: parseInt(dataAttr.getNamedItem("selectedPicks").value, 10),
                                        unSelectedPicks: dataAttr.getNamedItem("unSelectedPicks").value.split("|").map(Number)
                                    };
                                    pickBonusFeatureInfo.pickData = pData;
                                }
                                else if (pickBonusFeatureInfo.pickLevel === 1) {
                                    var pData1 = {
                                        pickIndex: parseInt(dataAttr.getNamedItem("pickIndex").value, 10),
                                        totalPicksAwarded: parseInt(dataAttr.getNamedItem("totalPicksAwarded").value, 10),
                                        currentPickGameNumber: parseInt(dataAttr.getNamedItem("currentPickGameNumber").value, 10),
                                        selectedPickAward: parseInt(dataAttr.getNamedItem("selectedPickAward").value, 10),
                                        prevSelectedAwards: this.parsePickTiles("prevSelectedAwards", dataAttr),
                                        unSelectedTiles: this.parsePickTiles("unSelectedTiles", dataAttr),
                                        pickAwardTable: this.parsePickTiles("pickAwardTable", dataAttr)
                                    };
                                    pickBonusFeatureInfo.pickEnd = luckytree.LTGamePlayDataXMLParser.extractBoolAttribute("pickEnd", dataAttr);
                                    pickBonusFeatureInfo.pickData = pData1;
                                    isBonusPay = true;
                                    totalBonusWin = pickBonusFeatureInfo.featureTotalWin;
                                }
                            }
                            if (featureTag.length > 1) {
                                pickBonusFeatureInfo.randomWildFeatureInfo = this.parseRandomFeatureInfo(featureTag);
                            }
                            customFeatureInfo = pickBonusFeatureInfo;
                            break;
                        case "3":
                            customFeatureInfo = this.parseRandomFeatureInfo(featureTag);
                            break;
                        default:
                            break;
                    }
                }
                var stakePerLine = Number(resultTag.attributes.getNamedItem("stakePerLine").value);
                BGReelData = new luckytree.LTBaseGameSpinData(reelData, customFeatureInfo, stakePerLine, gameData.getWager(), isMaxWin, maxWinValue);
                var baseGameRecovery = xml.getElementsByTagName("BaseGameRecoveryInfo")[0];
                if (isFeatureTriggered && baseGameRecovery != undefined) {
                    luckytree.LTGamePlayDataXMLParser.populateGameData(BGReelData.getBaseGameData(), baseGameRecovery, true, isFeatureTriggered, isBonusPay, totalBonusWin);
                    BGReelData.setBaseGameRandomWildInfo(this.parseRandomFeatureInfo(baseGameRecovery.childNodes));
                }
                // Open bet data, if available
                var payloadNode = xml.getElementsByTagName("Payload")[0];
                if (payloadNode != null) {
                    var openBetPayLoad = {};
                    openBetPayLoad = luckytree.LTOpenBetXMLParser.populateOpenBetPayLoad(payloadNode);
                    BGReelData.setOpenBetPayLoadInfo(openBetPayLoad);
                }
                response.getGameData().setCustomData(BGReelData);
                return response;
            }

