                var _this = this;
                this.slot = slot;
                this.slot.getEvents().add({
                    onSpinComplete: function () {
                        if (!_this.isRecovering)
                            _this.handleSpinComplete();
                    },
                    onSkillStop: null,
                    onGaffReel: null
                });
                this.slot.getRandomWildView().getEvents().add({
                    onUpdate: function () {
                        if (_this.gameState === 0 /* BaseGameSpin */ || _this.gameState === 4 /* BaseGameSpinTriggerFreeSpin */ || _this.gameState === 2 /* PickGameTrigger */) {
                            _this.slot.updateSymbolsWithRandomWild(_this.getRandomWildFeatureInfo());
                            _this.audioController.playCoinRevealSnd();
                        }
